import { Link } from "react-router-dom"

export default function Navbar() {

    const navbarLists = [
        {
            label: "useState",
            link: "/",
        },
        {
            label: "useEffect",
            link: "/use_effect",
        }
    ]

    return (
        <div>
           {navbarLists.map((e) => ( 
                <Link to={e.link} key={e.label} className="text-sm">{e.label}</Link>
           ))}
        </div> 
    )
}
